icle><article><i class="fas fa-truck-fast"></i><strong>{{ l('配送问题','Delivery help') }}</strong><p>{{ l('从本店 Tracking 进入已记录的承运与位置更新。','Use this store’s Tracking for recorded carrier and location updates.') }}</p></article><article><i class="fas fa-rotate-left"></i><strong>{{ l('取消与售后','Cancellation & aftercare') }}</strong><p>{{ l('可取消状态由 Shopping 订单真相决定。','Eligibility follows the Shopping order state.') }}</p></article></div><section class="cp-help-orders"><p>RECENT ORDERS</p><button v-for="order in orders" :key="order.id" :data-testid="`shopping-service-order-${order.id}`" @click="emit('open-order',order.id)"><span>{{ orderStatusLabel(order.status) }}</span><strong>{{ order.items.map(x=>x.title).join(' / ') }}</strong><b>{{ formatOrderTotal(order) }}</b></button></section></section></main></template>
